import React, { useState, useEffect } from 'react';
import { getAvailableForms, sendMessage } from './services/api';
import './App.css'; // Make sure your CSS styles are imported!

function App() {
  const [forms, setForms] = useState([]);
  const [selectedForm, setSelectedForm] = useState('');
  const [sessionId, setSessionId] = useState(`session_${Date.now()}`);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [collectedData, setCollectedData] = useState({});

  // 1. Fetch available forms dynamically on load
  useEffect(() => {
    getAvailableForms()
      .then((data) => {
        if (data.forms && data.forms.length > 0) {
          setForms(data.forms);
          setSelectedForm(data.forms[0]);
        }
      })
      .catch((err) => console.error("Error fetching forms:", err));
  }, []);

  // 2. Trigger initial greeting/prompt when form or session changes
  useEffect(() => {
    if (!selectedForm) return;

    sendMessage(sessionId, selectedForm, "")
      .then((data) => {
        if (data.response) {
          setMessages([{ sender: "bot", text: data.response }]);
        }
        setCollectedData(data.current_state || {});
      })
      .catch((err) => console.error("Error initializing chat:", err));
  }, [selectedForm, sessionId]);

  // Handle switching forms
  const handleFormChange = (e) => {
    const newForm = e.target.value;
    setSelectedForm(newForm);
    setSessionId(`session_${Date.now()}`); // Generate clean session ID for new form
  };

  // Handle sending user input
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;

    const userText = input;
    setInput('');
    setMessages((prev) => [...prev, { sender: "user", text: userText }]);

    try {
      const data = await sendMessage(sessionId, selectedForm, userText);
      if (data.response) {
        setMessages((prev) => [...prev, { sender: "bot", text: data.response }]);
      }
      setCollectedData(data.current_state || {});
    } catch (err) {
      console.error("Error sending message:", err);
    }
  };

  return (
    <div className="app-container" style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      {/* Top Header */}
      <header className="header" style={{ marginBottom: '20px' }}>
        <h2>Plateau Form Assistant</h2>
        <div className="form-selector" style={{ marginTop: '10px' }}>
          <label style={{ fontWeight: 'bold', marginRight: '8px' }}>Active Form: </label>
          <select 
            value={selectedForm} 
            onChange={handleFormChange}
            style={{ padding: '6px 12px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            {forms.map((f) => (
              <option key={f} value={f}>
                {f.replace('_', ' ').toUpperCase()}
              </option>
            ))}
          </select>
        </div>
      </header>

      {/* Main Container Split: Chat on Left, Data on Right */}
      <div style={{ display: 'flex', gap: '30px', alignItems: 'flex-start' }}>

        {/* Chat Section */}
        <div style={{ flex: '1', backgroundColor: '#f9f9f9', padding: '20px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
          <h3>Conversational Assistant</h3>

          <div style={{ minHeight: '250px', maxHeight: '400px', overflowY: 'auto', marginBottom: '15px' }}>
            {messages.map((m, i) => (
              <div 
                key={i} 
                style={{
                  margin: '10px 0',
                  padding: '10px 14px',
                  borderRadius: '6px',
                  backgroundColor: m.sender === 'user' ? '#e3f2fd' : '#ffffff',
                  border: '1px solid #ddd',
                  maxWidth: '80%'
                }}
              >
                <strong>{m.sender === 'user' ? 'You' : 'Assistant'}:</strong> {m.text}
              </div>
            ))}
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', gap: '10px' }}>
            <input 
              type="text"
              value={input} 
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your response..."
              style={{ flex: 1, padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
            <button 
              type="submit" 
              style={{ padding: '10px 20px', backgroundColor: '#f07c65', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
            >
              Send
            </button>
          </form>
        </div>

        {/* Form Progress Side Panel */}
        <div style={{ width: '320px', backgroundColor: '#fff', padding: '20px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
          <h4 style={{ marginTop: 0 }}>Form Progress</h4>
          <p style={{ fontSize: '12px', color: '#666', fontWeight: 'bold' }}>COLLECTED DATA</p>
          <pre style={{ backgroundColor: '#f4f4f4', padding: '10px', borderRadius: '4px', fontSize: '13px' }}>
            {JSON.stringify(collectedData, null, 2)}
          </pre>
        </div>

      </div>
    </div>
  );
}

export default App;
